class Dog:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def bark(self):
        return f'{self.name} says Woof!'

dog = Dog('Rex', 3)
print(dog.bark())
print(f'{dog.name} is {dog.age} years old')

class Student:
    def __init__(self, name, grade):
        self.name = name
        self.grade = grade

    def is_passing(self):
        return self.grade >= 60

s = Student('Alice', 85)
print(f'{s.name}: {"及格" if s.is_passing() else "不及格"}')

class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount
        return f'存入{amount}元，余额{self.balance}元'

    def withdraw(self, amount):
        if amount > self.balance:
            return '余额不足'
        self.balance -= amount
        return f'取出{amount}元，余额{self.balance}元'

account = BankAccount('Alice', 1000)
print(account.deposit(500))
print(account.withdraw(200))

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return '...'

class Cat(Animal):
    def speak(self):
        return f'{self.name} says Meow!'

class Dog(Animal):
    def speak(self):
        return f'{self.name} says Woof!'

for animal in [Cat('Kitty'), Dog('Rex')]:
    print(animal.speak())

class Shape:
    def area(self):
        return 0

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return 3.14 * self.radius ** 2

c = Circle(5)
print(f'圆形面积: {c.area()}')

class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def bonus(self):
        return self.salary * 0.1

class Manager(Employee):
    def bonus(self):
        return self.salary * 0.2

def print_bonus(emp):
    print(f'{emp.name}的奖金: {emp.bonus()}')

print_bonus(Employee('Alice', 10000))
print_bonus(Manager('Bob', 15000))
